@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private int highestCompletedStep = -1;
    private string errorMessage = string.Empty;
    private bool isValidating = false;
    private bool isSubmitting = false;
    private bool submitted = false;
    private int applicationId = 0;

    // Step 1 — Personal Info
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 — Work History
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 — References
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 — Cover Letter
    private string coverLetter = string.Empty;

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int step) => step <= highestCompletedStep;

    private void NavigateToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            currentStep = step;
            errorMessage = string.Empty;
        }
    }

    private async Task NextStep()
    {
        errorMessage = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (currentStep == 0)
        {
            isValidating = true;
            StateHasChanged();
            var emailValid = await ApplicationService.ValidateEmailAsync(email);
            isValidating = false;
            if (!emailValid)
            {
                errorMessage = "Please enter a valid email address.";
                return;
            }
        }

        if (currentStep > highestCompletedStep)
            highestCompletedStep = currentStep;

        currentStep++;
    }

    private void PreviousStep()
    {
        if (currentStep > 0)
        {
            currentStep--;
            errorMessage = string.Empty;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
                    string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
                {
                    errorMessage = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
                    {
                        errorMessage = "Please complete all required fields for each work entry.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var r in references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
                    {
                        errorMessage = "Please complete all required fields for each reference.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(coverLetter))
                {
                    errorMessage = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        errorMessage = string.Empty;
        StateHasChanged();

        var personal = new PersonalInfo(fullName, email, phone, address);
        var work = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, work, refs, coverLetter);

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
        submitted = true;

        // Mark final step as completed
        highestCompletedStep = 4;
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

